Here is a complete C program that includes the **Quicksort** and **Merge Sort** implementations, along with a **benchmark harness**.

This harness:
1.  Generates random arrays of sizes 100, 1,000, and 10,000.
2.  Runs each algorithm 100 times per size to average out system noise.
3.  Measures execution time using `clock()`.
4.  Prints the results in a formatted table.

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// --- Quicksort Implementation (Lomuto Partition) ---

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int partition(int arr[], int low, int high) {
    int pivot = arr[high];
    int i = (low - 1);

    for (int j = low; j <= high - 1; j++) {
        if (arr[j] < pivot) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return (i + 1);
}

void quickSort(int arr[], int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

// --- Merge Sort Implementation ---

void merge(int arr[], int l, int m, int r) {
    int n1 = m - l + 1;
    int n2 = r - m;

    int *L = (int *)malloc(n1 * sizeof(int));
    int *R = (int *)malloc(n2 * sizeof(int));

    for (int i = 0; i < n1; i++) L[i] = arr[l + i];
    for (int j = 0; j < n2; j++) R[j] = arr[m + 1 + j];

    int i = 0, j = 0, k = l;
    while (i < n1 && j < n2) {
        if (L[i] <= R[j]) {
            arr[k] = L[i];
            i++;
        } else {
            arr[k] = R[j];
            j++;
        }
        k++;
    }
    while (i < n1) { arr[k] = L[i]; i++; k++; }
    while (j < n2) { arr[k] = R[j]; j++; k++; }

    free(L);
    free(R);
}

void mergeSort(int arr[], int l, int r) {
    if (l < r) {
        int m = l + (r - l) / 2;
        mergeSort(arr, l, m);
        mergeSort(arr, m + 1, r);
        merge(arr, l, m, r);
    }
}

// --- Benchmark Harness ---

#define NUM_RUNS 100
#define SIZES_COUNT 3

// Array of sizes to test
int test_sizes[] = {100, 1000, 10000};

/**
 * Function: generate_random_array
 * --------------------------------
 * Allocates memory and fills an array with random integers.
 */
int* generate_random_array(int size) {
    int *arr = (int *)malloc(size * sizeof(int));
    if (!arr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    for (int i = 0; i < size; i++) {
        arr[i] = rand() % 100000; // Random numbers between 0 and 99999
    }
    return arr;
}

/**
 * Function: copy_array
 * --------------------
 * Creates a deep copy of an array to ensure fair testing (both algos get same data).
 */
int* copy_array(int *src, int size) {
    int *dest = (int *)malloc(size * sizeof(int));
    if (!dest) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    memcpy(dest, src, size * sizeof(int));
    return dest;
}

/**
 * Function: run_benchmark
 * -----------------------
 * Runs a specific sorting algorithm on a specific array size multiple times
 * and returns the average time in milliseconds.
 */
double run_benchmark(int (*sort_func)(int*, int, int), int size) {
    double total_time = 0.0;

    // We run the test NUM_RUNS times to get a stable average
    for (int run = 0; run < NUM_RUNS; run++) {
        int *arr = generate_random_array(size);

        clock_t start = clock();

        // Call the sorting function
        // Note: We cast the function pointer to match the signature expected
        // Since quickSort and mergeSort have the same signature (int*, int, int)
        // we can pass them directly.
        sort_func(arr, 0, size - 1);

        clock_t end = clock();

        double time_spent = ((double)(end - start)) / CLOCKS_PER_SEC;
        total_time += time_spent;

        free(arr);
    }

    // Return average time in milliseconds
    return (total_time / NUM_RUNS) * 1000.0;
}

int main() {
    // Seed random number generator
    srand(time(NULL));

    printf("Sorting Algorithm Benchmark\n");
    printf("Running %d iterations per size...\n\n", NUM_RUNS);

    // Print Table Header
    printf("%-10s | %-15s | %-15s | %-10s\n", "Size", "Quicksort (ms)", "Merge Sort (ms)", "Ratio (Q/M)");
    printf("---------|-----------------|-----------------|----------\n");

    for (int i = 0; i < SIZES_COUNT; i++) {
        int size = test_sizes[i];

        // Benchmark Quicksort
        double q_time = run_benchmark((int (*)(int*, int, int))quickSort, size);

        // Benchmark Merge Sort
        double m_time = run_benchmark((int (*)(int*, int, int))mergeSort, size);

        // Calculate ratio (Quicksort time / Merge Sort time)
        // If Merge Sort is faster, ratio < 1. If Quicksort is faster, ratio > 1.
        double ratio = (m_time > 0) ? (q_time / m_time) : 0.0;

        printf("%-10d | %-15.4f | %-15.4f | %-10.2f\n", 
               size, q_time, m_time, ratio);
    }

    printf("\nNote: Times are averages over %d runs.\n", NUM_RUNS);
    printf("Ratio > 1.0 means Quicksort was slower than Merge Sort for that size.\n");
    printf("Ratio < 1.0 means Quicksort was faster.\n");

    return 0;
}
```

### How to Compile and Run

1.  Save the code to a file named `benchmark.c`.
2.  Compile it using `gcc`:
    ```bash
    gcc -o benchmark benchmark.c -O2
    ```
    *Note: The `-O2` flag enables compiler optimizations, which makes the benchmark more realistic for production code.*
3.  Run the executable:
    ```bash
    ./benchmark
    ```

### Expected Output Format

The output will look like this (values will vary based on your CPU and system load):

```text
Sorting Algorithm Benchmark
Running 100 iterations per size...

Size       | Quicksort (ms)  | Merge Sort (ms) | Ratio (Q/M)
---------|-----------------|-----------------|----------
100      | 0.0012          | 0.0015          | 0.80
1000     | 0.0145          | 0.0182          | 0.80
10000    | 0.1850          | 0.2100          | 0.88

Note: Times are averages over 100 runs.
Ratio > 1.0 means Quicksort was slower than Merge Sort for that size.
Ratio < 1.0 means Quicksort was faster.
```

### Key Observations from the Benchmark

1.  **Small Arrays (100)**: Both algorithms are extremely fast (sub-millisecond). The overhead of function calls and memory allocation in Merge Sort might make it slightly slower or comparable to Quicksort.
2.  **Medium/Large Arrays (1000 - 10000)**:
    *   **Quicksort** typically performs better in practice for random data due to better cache locality (it accesses memory sequentially more often) and lower constant factors (no extra memory allocation).
    *   **Merge Sort** is consistent but often slightly slower in raw speed for in-memory integer arrays because of the `malloc`/`free` overhead and the extra memory copying.
3.  **Ratio**: A ratio close to 1.0 indicates similar performance. A ratio significantly less than 1.0 indicates Quicksort is faster.

### Important Note on Randomness
Since `srand(time(NULL))` is used, the input data is random every time you run the program.
*   **Quicksort** is highly sensitive to the pivot choice. With random data, it usually hits the $O(n \log n)$ average case.
*   **Merge Sort** is immune to input distribution, always performing $O(n \log n)$.

If you want to test the **Worst Case** for Quicksort (where it degrades to $O(n^2)$), you would need to modify the `generate_random_array` function to create a **sorted** or **reverse-sorted** array. In that scenario, the Quicksort time would skyrocket compared to Merge Sort.
